"""Read-only replay verification of a saved ``simulate`` result.

``replay`` reruns the deterministic simulation on the original scenario and
compares the freshly computed result against the saved result field by field.
It never reads the wall clock, never uses randomness and never creates or
modifies files, so identical input produces byte-identical output.
"""

from __future__ import annotations

from .simulate import run_simulation


def _kind(value: object) -> str:
    """A JSON-level type tag. Booleans get their own tag so that ``true`` is
    never equal to the number 1, while ints and floats share ``number`` so
    that numbers compare by numeric value."""
    if value is None:
        return "null"
    if isinstance(value, bool):
        return "bool"
    if isinstance(value, (int, float)):
        return "number"
    if isinstance(value, str):
        return "string"
    if isinstance(value, list):
        return "array"
    return "object"


def _escape_token(token: str) -> str:
    """Escape one RFC 6901 reference token ('~' before '/')."""
    return token.replace("~", "~0").replace("/", "~1")


def _pointer(tokens: list[str]) -> str:
    if not tokens:
        return ""
    return "".join("/" + token for token in tokens)


def _first_difference(expected: object, actual: object, tokens: list[str]) -> str | None:
    """Return the RFC 6901 pointer of the first structural difference, or
    None when the two JSON values are equal.

    Arrays are compared by ascending index; objects recurse over the union of
    both sides' keys in ascending Unicode code-point order. A type or scalar
    difference ends the comparison at the current position; when an array
    prefix matches but the lengths differ, the pointer names the first
    missing index.
    """
    expected_kind = _kind(expected)
    actual_kind = _kind(actual)
    if expected_kind != actual_kind:
        return _pointer(tokens)

    if expected_kind in ("null", "bool", "number", "string"):
        if expected != actual:
            return _pointer(tokens)
        return None

    if expected_kind == "array":
        shared = min(len(expected), len(actual))
        for index in range(shared):
            found = _first_difference(expected[index], actual[index], tokens + [str(index)])
            if found is not None:
                return found
        if len(expected) != len(actual):
            return _pointer(tokens + [str(shared)])
        return None

    # Object: member order is irrelevant; visit the key union by Unicode code
    # point. A key present on only one side is itself the first difference.
    for key in sorted(set(expected) | set(actual)):
        token = _escape_token(key)
        if key not in expected or key not in actual:
            return _pointer(tokens + [token])
        found = _first_difference(expected[key], actual[key], tokens + [token])
        if found is not None:
            return found
    return None


def run_replay(scenario_raw: object, result_raw: object) -> dict:
    """Recompute the simulation for ``scenario_raw`` and compare it against
    the saved ``result_raw``.

    Returns ``{"status": "matched"}`` on equality, otherwise an object with
    ``status: "mismatched"``, the RFC 6901 pointer of the first difference,
    presence flags for both sides and the present value(s). Scenario
    validation errors propagate as :class:`ScenarioError` exactly as in
    ``simulate``.
    """
    expected = run_simulation(scenario_raw)

    path = _first_difference(expected, result_raw, [])
    if path is None:
        return {"status": "matched"}

    mismatch = {
        "status": "mismatched",
        "path": path,
        "expectedPresent": False,
        "actualPresent": False,
    }
    expected_value, actual_value = _value_at(expected, path), _value_at(result_raw, path)
    if expected_value is not _MISSING:
        mismatch["expectedPresent"] = True
        mismatch["expected"] = expected_value
    if actual_value is not _MISSING:
        mismatch["actualPresent"] = True
        mismatch["actual"] = actual_value
    return mismatch


class _Missing:
    """Sentinel for a pointer position absent on one side (distinct from a
    real JSON null, which is a present value)."""


_MISSING = _Missing()


def _value_at(root: object, path: str) -> object:
    """Resolve an RFC 6901 pointer produced by the comparison against one
    side. Returns the ``_MISSING`` sentinel when an object member or array
    index is absent."""
    if path == "":
        return root
    current = root
    for raw_token in path.split("/")[1:]:
        token = raw_token.replace("~1", "/").replace("~0", "~")
        if isinstance(current, dict):
            if token in current:
                current = current[token]
            else:
                return _MISSING
        elif isinstance(current, list) and token.isascii() and token.isdigit():
            index = int(token)
            if 0 <= index < len(current):
                current = current[index]
            else:
                return _MISSING
        else:
            return _MISSING
    return current

"""Bounded enumeration of message-fault combinations over a base scenario.

``explore`` reuses the deterministic simulator for every combination: it
never reads the wall clock, never uses randomness and never creates files,
so identical PLAN input produces byte-identical output.
"""

from __future__ import annotations

from itertools import combinations

from .simulate import ScenarioError, _Simulator, _require_int, parse_scenario

_PLAN_FIELDS = {
    "scenario",
    "candidates",
    "maxFaults",
    "maxCases",
    "minimizeFailures",
    "eventCandidates",
    "maxEventFaults",
}
_REQUIRED_PLAN_FIELDS = {"scenario", "candidates", "maxFaults", "maxCases"}
_EVENT_CANDIDATE_FIELDS = {"network", "node"}

# Reports whose violation lists decide a case's status. A report the scenario
# does not enable is absent from the result and plays no part in the verdict.
_CHECKED_REPORTS = (
    "electionSafety",
    "logMatching",
    "stateMachineSafety",
    "linearizability",
    "liveness",
)


def _failure_signature(result: dict) -> tuple[str, ...]:
    """Names of the enabled reports whose violation list is non-empty, in
    fixed check-priority order. Two cases share a failure signature exactly
    when they violate the same set of invariants."""
    return tuple(
        key
        for key in _CHECKED_REPORTS
        if key in result and result[key]["violations"]
    )


def _merged_config(
    scenario_raw: dict,
    candidates: list,
    event_candidates: list,
    event_selected: tuple[int, ...],
) -> dict:
    """Validate and normalize the scenario for one event combination: the
    base scenario with every message-fault candidate presented as its
    messageFaults and the selected events appended to the corresponding
    collections. Base entries keep their positions, so at one timestamp
    same-kind base events are processed before the selected candidates (in
    candidate-index order), and network events still precede node events."""
    merged = dict(scenario_raw)
    merged["messageFaults"] = candidates
    network = [
        event_candidates[i]["network"] for i in event_selected if "network" in event_candidates[i]
    ]
    node = [event_candidates[i]["node"] for i in event_selected if "node" in event_candidates[i]]
    if network or "faults" in merged:
        merged["faults"] = list(merged.get("faults", [])) + network
    if node or "nodeEvents" in merged:
        merged["nodeEvents"] = list(merged.get("nodeEvents", [])) + node
    return parse_scenario(merged)


def run_explore(raw: object) -> dict:
    """Validate a decoded JSON PLAN and run every fault combination."""
    if not isinstance(raw, dict):
        raise ScenarioError("plan must be a JSON object")
    unknown = sorted(set(raw) - _PLAN_FIELDS)
    if unknown:
        raise ScenarioError(f"unknown field(s): {', '.join(unknown)}")
    missing = sorted(_REQUIRED_PLAN_FIELDS - set(raw))
    if missing:
        raise ScenarioError(f"missing field(s): {', '.join(missing)}")

    has_event_candidates = "eventCandidates" in raw
    has_max_event_faults = "maxEventFaults" in raw
    if has_event_candidates != has_max_event_faults:
        raise ScenarioError(
            "eventCandidates and maxEventFaults must be provided together"
        )
    events_enabled = has_event_candidates

    minimize_failures = raw.get("minimizeFailures", False)
    if not isinstance(minimize_failures, bool):
        raise ScenarioError("minimizeFailures must be a boolean")

    scenario_raw = raw["scenario"]
    if not isinstance(scenario_raw, dict):
        raise ScenarioError("scenario must be a JSON object")
    if "messageFaults" in scenario_raw:
        raise ScenarioError("scenario must not contain messageFaults")

    candidates = raw["candidates"]
    if not isinstance(candidates, list):
        raise ScenarioError("candidates must be a list")
    if not candidates:
        raise ScenarioError("candidates must not be empty")

    max_faults = _require_int(raw["maxFaults"], "maxFaults", 0)
    if max_faults > len(candidates):
        raise ScenarioError("maxFaults must not exceed the number of candidates")
    max_cases = _require_int(raw["maxCases"], "maxCases", 1)

    event_candidates: list = []
    max_event_faults = 0
    if events_enabled:
        event_candidates = raw["eventCandidates"]
        if not isinstance(event_candidates, list):
            raise ScenarioError("eventCandidates must be a list")
        if not event_candidates:
            raise ScenarioError("eventCandidates must not be empty")
        for index, item in enumerate(event_candidates):
            label = f"eventCandidates[{index}]"
            if not isinstance(item, dict):
                raise ScenarioError(f"{label} must be an object")
            unknown = sorted(set(item) - _EVENT_CANDIDATE_FIELDS)
            if unknown:
                raise ScenarioError(
                    f"{label} has unknown field(s): {', '.join(unknown)}"
                )
            if len(set(item) & _EVENT_CANDIDATE_FIELDS) != 1:
                raise ScenarioError(
                    f"{label} must declare exactly one of network or node"
                )
        max_event_faults = _require_int(raw["maxEventFaults"], "maxEventFaults", 0)
        if max_event_faults > len(event_candidates):
            raise ScenarioError(
                "maxEventFaults must not exceed the number of event candidates"
            )

    # Validate the base scenario and every candidate rule with the original
    # scenario validation by presenting the candidates as its messageFaults;
    # this also rejects duplicated full selectors. Each normalized rule keeps
    # its candidate index in its "index" field.
    combined = dict(scenario_raw)
    combined["messageFaults"] = candidates
    config = parse_scenario(combined)
    rules = config["messageFaults"]

    # The empty combination comes first, then combinations of ascending size;
    # itertools.combinations yields index tuples in numeric lexicographic
    # order, and each tuple is ascending, so selected rules and events are
    # always injected in original candidate-index order.
    message_combos = [
        combo
        for size in range(max_faults + 1)
        for combo in combinations(range(len(candidates)), size)
    ]
    event_combos = [
        combo
        for size in range(max_event_faults + 1)
        for combo in combinations(range(len(event_candidates)), size)
    ]

    total = len(message_combos) * len(event_combos)
    if total > max_cases:
        raise ScenarioError(
            f"combination count {total} exceeds maxCases {max_cases}"
        )

    if events_enabled:
        # Every merged scenario is validated before any simulation runs:
        # first each event candidate on its own (in the base context, exactly
        # like the message-fault candidates above), then every enumerated
        # combination, whose appended events may jointly violate a constraint
        # such as crash/restart alternation.
        for index in range(len(event_candidates)):
            _merged_config(scenario_raw, candidates, event_candidates, (index,))
        event_configs = [
            _merged_config(scenario_raw, candidates, event_candidates, combo)
            for combo in event_combos
        ]
    else:
        event_configs = [config]

    # Message-fault combinations form the outer loop in their established
    # order; within each, the empty event combination comes first, then
    # event combinations of ascending size in numeric lexicographic order.
    cases = []
    # Only populated while minimizing: signature -> list of
    # (selected index tuple, selected event index tuple, caseId).
    # Minimization never runs extra simulations; it only references cases
    # enumerated here, so those references do not count against maxCases.
    by_signature: dict[
        tuple[str, ...], list[tuple[tuple[int, ...], tuple[int, ...], int]]
    ] = {}
    passed = 0
    case_id = 0
    for selected in message_combos:
        for event_index, event_selected in enumerate(event_combos):
            case_config = dict(event_configs[event_index])
            case_config["messageFaults"] = [rules[i] for i in selected]
            result = _Simulator(case_config).run()
            signature = _failure_signature(result)
            if signature:
                status = "failed"
            else:
                status = "passed"
                passed += 1
            case = {"caseId": case_id, "selected": list(selected)}
            if events_enabled:
                case["selectedEvents"] = list(event_selected)
            case["status"] = status
            case["result"] = result
            if minimize_failures and signature:
                by_signature.setdefault(signature, []).append(
                    (selected, event_selected, case_id)
                )
            cases.append(case)
            case_id += 1

    if minimize_failures:
        for case in cases:
            if case["status"] != "failed":
                continue
            signature = _failure_signature(case["result"])
            selected = tuple(case["selected"])
            selected_events = tuple(case.get("selectedEvents", ()))
            # Every minimizing combination must be reachable by deleting
            # candidates of both kinds from this case (sub-combinations of
            # its selected indices) and reproduce its exact failure
            # signature: a combination that passes or that only shows other
            # violations is never selected. The fewest total candidates win;
            # ties are broken by the numeric lexicographic order of the
            # selected index array, then of the selectedEvents array. The
            # case itself always qualifies.
            minimal_selected, minimal_events, minimal_case_id = min(
                (
                    entry
                    for entry in by_signature[signature]
                    if set(entry[0]).issubset(selected)
                    and set(entry[1]).issubset(selected_events)
                ),
                key=lambda entry: (len(entry[0]) + len(entry[1]), entry[0], entry[1]),
            )
            case["failureReports"] = list(signature)
            case["minimalSelected"] = list(minimal_selected)
            if events_enabled:
                case["minimalSelectedEvents"] = list(minimal_events)
            case["minimalCaseId"] = minimal_case_id

    return {
        "totalCases": len(cases),
        "passedCases": passed,
        "failedCases": len(cases) - passed,
        "cases": cases,
    }

"""Command line entry point for consensus-protocol-lab."""

from __future__ import annotations

import argparse
import json
import sys

from . import __version__
from .explore import run_explore
from .replay import run_replay
from .simulate import ScenarioError, run_simulation


def _cmd_simulate(path: str) -> int:
    try:
        with open(path, "r", encoding="utf-8") as handle:
            text = handle.read()
    except OSError as exc:
        print(f"error: cannot read scenario file: {exc}", file=sys.stderr)
        return 2
    except UnicodeDecodeError:
        print(f"error: scenario file is not valid UTF-8: {path}", file=sys.stderr)
        return 2
    try:
        raw = json.loads(text)
    except json.JSONDecodeError as exc:
        print(f"error: invalid JSON: {exc}", file=sys.stderr)
        return 2
    try:
        result = run_simulation(raw)
    except ScenarioError as exc:
        print(f"error: {exc}", file=sys.stderr)
        return 2
    print(json.dumps(result, ensure_ascii=False, indent=2))
    return 0


def _cmd_explore(path: str) -> int:
    try:
        with open(path, "r", encoding="utf-8") as handle:
            text = handle.read()
    except OSError as exc:
        print(f"error: cannot read plan file: {exc}", file=sys.stderr)
        return 2
    except UnicodeDecodeError:
        print(f"error: plan file is not valid UTF-8: {path}", file=sys.stderr)
        return 2
    try:
        raw = json.loads(text)
    except json.JSONDecodeError as exc:
        print(f"error: invalid JSON: {exc}", file=sys.stderr)
        return 2
    try:
        result = run_explore(raw)
    except ScenarioError as exc:
        print(f"error: {exc}", file=sys.stderr)
        return 2
    print(json.dumps(result, ensure_ascii=False, indent=2))
    return 0


def _read_utf8_json(path: str, kind: str) -> tuple[bool, object]:
    """Read and decode a UTF-8 JSON file for replay. Returns (ok, value);
    on failure prints one ``error:`` line to stderr and returns (False,
    None). ``kind`` labels the file in the messages."""
    try:
        with open(path, "r", encoding="utf-8") as handle:
            text = handle.read()
    except OSError as exc:
        print(f"error: cannot read {kind} file: {exc}", file=sys.stderr)
        return False, None
    except UnicodeDecodeError:
        print(f"error: {kind} file is not valid UTF-8: {path}", file=sys.stderr)
        return False, None
    try:
        # parse_constant rejects the non-standard NaN/Infinity tokens that
        # Python's decoder otherwise accepts; strict JSON treats them as
        # syntax errors.
        return True, json.loads(text, parse_constant=_reject_json_constant)
    except (json.JSONDecodeError, ValueError) as exc:
        print(f"error: invalid JSON in {kind} file: {exc}", file=sys.stderr)
        return False, None


def _reject_json_constant(value: str) -> None:
    raise ValueError(f"invalid JSON token: {value}")


def _cmd_replay(scenario_path: str, result_path: str) -> int:
    ok, scenario_raw = _read_utf8_json(scenario_path, "scenario")
    if not ok:
        return 2
    ok, result_raw = _read_utf8_json(result_path, "result")
    if not ok:
        return 2
    # A non-object RESULT cannot carry the comparison contract (status is
    # reported as mismatched only when the top level is an object).
    if not isinstance(result_raw, dict):
        print("error: result file must contain a JSON object", file=sys.stderr)
        return 2
    try:
        report = run_replay(scenario_raw, result_raw)
    except ScenarioError as exc:
        print(f"error: {exc}", file=sys.stderr)
        return 2
    # Compact, member order fixed by construction: byte-identical for
    # identical input.
    print(json.dumps(report, ensure_ascii=False, separators=(",", ":")))
    return 0 if report["status"] == "matched" else 1


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(prog="consensus-protocol-lab", description="Deterministic simulation lab for Raft-style consensus protocols")
    sub = parser.add_subparsers(dest="command")
    sub.add_parser("version", help="print the current version")
    simulate = sub.add_parser("simulate", help="run a deterministic Raft leader-election simulation")
    simulate.add_argument("scenario", help="path to a UTF-8 JSON scenario file")
    explore = sub.add_parser("explore", help="enumerate bounded message-fault combinations over a base scenario")
    explore.add_argument("plan", help="path to a UTF-8 JSON plan file")
    replay = sub.add_parser("replay", help="recompute a simulation and field-compare it against a saved result")
    replay.add_argument("scenario", help="path to the UTF-8 JSON scenario file")
    replay.add_argument("result", help="path to a UTF-8 JSON file holding a simulate result")
    args = parser.parse_args(argv)

    if args.command == "version":
        print(__version__)
        return 0
    if args.command == "simulate":
        return _cmd_simulate(args.scenario)
    if args.command == "explore":
        return _cmd_explore(args.plan)
    if args.command == "replay":
        return _cmd_replay(args.scenario, args.result)

    parser.print_help()
    return 0


if __name__ == "__main__":
    sys.exit(main())

"""Deterministic Raft leader-election and log-replication simulation.

The simulation advances virtual time only: it never reads the wall clock and
never uses randomness, so identical input produces byte-identical output.
"""

from __future__ import annotations

import heapq
import json

ROLE_FOLLOWER = "follower"
ROLE_CANDIDATE = "candidate"
ROLE_LEADER = "leader"
# Optional pre-vote phase: a preCandidate probes the cluster with a
# prospective term (current term + 1) without touching its persisted term or
# votedFor, so a node rejoining after an isolation gap cannot disrupt a
# stable leader with a meaningless high term.
ROLE_PRECANDIDATE = "preCandidate"

# Event kinds, processed in this order when they share a timestamp.
_KIND_FAULT = 0
_KIND_NODE_EVENT = 1
_KIND_MESSAGE = 2
_KIND_CLIENT = 3
# Replication traffic triggered by client commands (and its replies) lands
# here so that, even with zero message delay, all client commands sharing a
# timestamp are handled in input order before their reactions drain.
_KIND_REACTION = 4
# Membership requests sit behind every pending reaction: the heap keeps
# (t, REACTION, ...) entries ahead of (t, MEMBERSHIP, ...), so a request's own
# zero-delay cascade likewise drains before the next timed event.
_KIND_MEMBERSHIP = 5
# Read-only queries are accepted after faults, node events, arrived messages,
# client commands (and their zero-delay reactions) and membership requests,
# and before timeouts and heartbeats; a query's own zero-delay probe cascade
# likewise drains before the next timed event.
_KIND_READ = 6
_KIND_TIMEOUT = 7
_KIND_HEARTBEAT = 8
# Liveness checks are evaluated after every pre-existing event (and its
# zero-delay reaction cascade) sharing the timestamp has drained, so this is
# the largest event kind.
_KIND_LIVENESS = 9

_TOP_LEVEL_FIELDS = {
    "nodes",
    "duration",
    "electionTimeouts",
    "heartbeatInterval",
    "messageDelay",
    "faults",
    "clientCommands",
    "nodeEvents",
    "snapshotThreshold",
    "initialMembers",
    "membershipChanges",
    "messageFaults",
    "readQueries",
    "livenessChecks",
    "preVote",
}
_REQUIRED_FIELDS = _TOP_LEVEL_FIELDS - {
    "faults",
    "clientCommands",
    "nodeEvents",
    "snapshotThreshold",
    "initialMembers",
    "membershipChanges",
    "messageFaults",
    "readQueries",
    "livenessChecks",
    "preVote",
}
_FAULT_FIELDS = {"time", "action", "groups"}
_MESSAGE_FAULT_FIELDS = {"from", "to", "message", "occurrence", "action", "delay"}
_MESSAGE_FAULT_REQUIRED = {"from", "to", "message", "occurrence", "action"}
_MESSAGE_KINDS = (
    "requestVote",
    "voteReply",
    "preVote",
    "preVoteReply",
    "heartbeat",
    "appendEntries",
    "appendReply",
    "installSnapshot",
    "installSnapshotReply",
    "readProbe",
    "readReply",
)
# Pre-vote traffic exists only while the optional phase is enabled; a rule
# referencing either kind in a preVote-less scenario makes the scenario illegal.
_PRE_VOTE_MESSAGE_KINDS = ("preVote", "preVoteReply")
_CLIENT_COMMAND_FIELDS = {"time", "node", "id", "command"}
_NODE_EVENT_FIELDS = {"time", "node", "action"}
_MEMBERSHIP_CHANGE_FIELDS = {"time", "node", "id", "action", "member"}
_READ_QUERY_FIELDS = {"time", "node", "id"}
_LIVENESS_CHECK_FIELDS = {"id", "type", "startTime", "deadline", "target"}
_LIVENESS_TYPES = (
    "leaderElected",
    "clientCommitted",
    "readCompleted",
    "membershipCommitted",
)
_LIVENESS_TARGET_TYPES = {
    "clientCommitted": "clientCommands",
    "readCompleted": "readQueries",
    "membershipCommitted": "membershipChanges",
}

# Log-entry kinds: ordinary client commands versus replicated configuration
# entries created by joint-consensus membership changes.
KIND_COMMAND = "command"
KIND_CONFIG = "config"
CONFIG_JOINT = "joint"
CONFIG_STABLE = "stable"


class ScenarioError(Exception):
    """The scenario input is invalid."""


def _is_int(value: object) -> bool:
    return isinstance(value, int) and not isinstance(value, bool)


def _require_int(value: object, name: str, minimum: int) -> int:
    if not _is_int(value):
        raise ScenarioError(f"{name} must be an integer")
    if value < minimum:
        if minimum > 0:
            raise ScenarioError(f"{name} must be a positive integer")
        raise ScenarioError(f"{name} must be a non-negative integer")
    return value


def parse_scenario(raw: object) -> dict:
    """Validate the decoded JSON scenario and return a normalized config."""
    if not isinstance(raw, dict):
        raise ScenarioError("scenario must be a JSON object")
    unknown = sorted(set(raw) - _TOP_LEVEL_FIELDS)
    if unknown:
        raise ScenarioError(f"unknown field(s): {', '.join(unknown)}")
    missing = sorted(_REQUIRED_FIELDS - set(raw))
    if missing:
        raise ScenarioError(f"missing field(s): {', '.join(missing)}")

    nodes = raw["nodes"]
    if not isinstance(nodes, list) or len(nodes) < 3:
        raise ScenarioError("nodes must be a list of at least three names")
    for name in nodes:
        if not isinstance(name, str) or not name:
            raise ScenarioError("node names must be non-empty strings")
    if len(set(nodes)) != len(nodes):
        raise ScenarioError("node names must be unique")

    duration = _require_int(raw["duration"], "duration", 0)
    heartbeat = _require_int(raw["heartbeatInterval"], "heartbeatInterval", 1)
    delay = _require_int(raw["messageDelay"], "messageDelay", 0)

    timeouts_raw = raw["electionTimeouts"]
    if _is_int(timeouts_raw):
        _require_int(timeouts_raw, "electionTimeouts", 1)
        timeouts = {name: timeouts_raw for name in nodes}
    elif isinstance(timeouts_raw, dict):
        unknown_nodes = sorted(set(timeouts_raw) - set(nodes))
        if unknown_nodes:
            raise ScenarioError(
                f"electionTimeouts references unknown node(s): {', '.join(unknown_nodes)}"
            )
        missing_nodes = sorted(set(nodes) - set(timeouts_raw))
        if missing_nodes:
            raise ScenarioError(
                f"electionTimeouts is missing node(s): {', '.join(missing_nodes)}"
            )
        timeouts = {}
        for name in nodes:
            timeouts[name] = _require_int(timeouts_raw[name], f"electionTimeouts.{name}", 1)
    else:
        raise ScenarioError("electionTimeouts must be a positive integer or an object mapping node names to positive integers")

    # The optional pre-vote phase is opt-in: omitted or false keeps every
    # legacy scenario's behavior (and output) byte for byte, and the
    # pre-vote message kinds become illegal.
    pre_vote = raw.get("preVote", False)
    if not isinstance(pre_vote, bool):
        raise ScenarioError("preVote must be a boolean")

    faults = raw.get("faults", [])
    if not isinstance(faults, list):
        raise ScenarioError("faults must be a list")
    normalized_faults = []
    node_set = set(nodes)
    for index, fault in enumerate(faults):
        label = f"faults[{index}]"
        if not isinstance(fault, dict):
            raise ScenarioError(f"{label} must be an object")
        unknown = sorted(set(fault) - _FAULT_FIELDS)
        if unknown:
            raise ScenarioError(f"{label} has unknown field(s): {', '.join(unknown)}")
        if "time" not in fault or "action" not in fault:
            raise ScenarioError(f"{label} must have time and action")
        time = _require_int(fault["time"], f"{label}.time", 0)
        if time > duration:
            raise ScenarioError(f"{label}.time is beyond the simulation duration")
        action = fault["action"]
        if action == "partition":
            if "groups" not in fault:
                raise ScenarioError(f"{label} partition requires groups")
            groups = fault["groups"]
            if not isinstance(groups, list) or len(groups) != 2:
                raise ScenarioError(f"{label}.groups must contain exactly two groups")
            seen: set[str] = set()
            normalized_groups = []
            for group in groups:
                if not isinstance(group, list) or not group:
                    raise ScenarioError(f"{label}.groups entries must be non-empty lists")
                for member in group:
                    if member not in node_set:
                        raise ScenarioError(f"{label}.groups references unknown node: {member!r}")
                    if member in seen:
                        raise ScenarioError(f"{label}.groups must not overlap")
                    seen.add(member)
                normalized_groups.append(list(group))
            if seen != node_set:
                raise ScenarioError(f"{label}.groups must cover every node")
            normalized_faults.append({"time": time, "action": "partition", "groups": normalized_groups})
        elif action == "heal":
            if "groups" in fault:
                raise ScenarioError(f"{label} heal must not have groups")
            normalized_faults.append({"time": time, "action": "heal"})
        else:
            raise ScenarioError(f"{label}.action must be partition or heal")

    message_faults = raw.get("messageFaults", [])
    if not isinstance(message_faults, list):
        raise ScenarioError("messageFaults must be a list")
    normalized_message_faults = []
    seen_selectors: dict[tuple, int] = {}
    for index, message_fault in enumerate(message_faults):
        label = f"messageFaults[{index}]"
        if not isinstance(message_fault, dict):
            raise ScenarioError(f"{label} must be an object")
        unknown = sorted(set(message_fault) - _MESSAGE_FAULT_FIELDS)
        if unknown:
            raise ScenarioError(f"{label} has unknown field(s): {', '.join(unknown)}")
        missing = sorted(_MESSAGE_FAULT_REQUIRED - set(message_fault))
        if missing:
            raise ScenarioError(f"{label} missing field(s): {', '.join(missing)}")
        src = message_fault["from"]
        if not isinstance(src, str) or not src:
            raise ScenarioError(f"{label}.from must be a non-empty string")
        if src not in node_set:
            raise ScenarioError(f"{label}.from references unknown node: {src!r}")
        dst = message_fault["to"]
        if not isinstance(dst, str) or not dst:
            raise ScenarioError(f"{label}.to must be a non-empty string")
        if dst not in node_set:
            raise ScenarioError(f"{label}.to references unknown node: {dst!r}")
        if src == dst:
            raise ScenarioError(f"{label}.from and {label}.to must be different nodes")
        kind = message_fault["message"]
        if kind in _PRE_VOTE_MESSAGE_KINDS and not pre_vote:
            raise ScenarioError(
                f"{label}.message {kind!r} is only valid when preVote is enabled"
            )
        if kind not in _MESSAGE_KINDS:
            raise ScenarioError(
                f"{label}.message must be one of: {', '.join(_MESSAGE_KINDS)}"
            )
        occurrence = _require_int(message_fault["occurrence"], f"{label}.occurrence", 1)
        action = message_fault["action"]
        if action not in ("drop", "delay"):
            raise ScenarioError(f"{label}.action must be drop or delay")
        extra_delay = None
        if action == "drop":
            if "delay" in message_fault:
                raise ScenarioError(f"{label} drop must not have delay")
        else:
            if "delay" not in message_fault:
                raise ScenarioError(f"{label} delay requires delay")
            extra_delay = _require_int(message_fault["delay"], f"{label}.delay", 0)
        selector = (src, dst, kind, occurrence)
        if selector in seen_selectors:
            raise ScenarioError(
                f"{label} duplicates the selector of messageFaults[{seen_selectors[selector]}]"
            )
        seen_selectors[selector] = index
        normalized = {
            "index": index,
            "from": src,
            "to": dst,
            "message": kind,
            "occurrence": occurrence,
            "action": action,
        }
        if extra_delay is not None:
            normalized["delay"] = extra_delay
        normalized_message_faults.append(normalized)

    commands = raw.get("clientCommands", [])
    if not isinstance(commands, list):
        raise ScenarioError("clientCommands must be a list")
    normalized_commands = []
    seen_ids: set[str] = set()
    for index, command in enumerate(commands):
        label = f"clientCommands[{index}]"
        if not isinstance(command, dict):
            raise ScenarioError(f"{label} must be an object")
        unknown = sorted(set(command) - _CLIENT_COMMAND_FIELDS)
        if unknown:
            raise ScenarioError(f"{label} has unknown field(s): {', '.join(unknown)}")
        missing = sorted(_CLIENT_COMMAND_FIELDS - set(command))
        if missing:
            raise ScenarioError(f"{label} missing field(s): {', '.join(missing)}")
        time = _require_int(command["time"], f"{label}.time", 0)
        if time > duration:
            raise ScenarioError(f"{label}.time is beyond the simulation duration")
        node = command["node"]
        if not isinstance(node, str) or not node:
            raise ScenarioError(f"{label}.node must be a non-empty string")
        if node not in node_set:
            raise ScenarioError(f"{label}.node references unknown node: {node!r}")
        command_id = command["id"]
        if not isinstance(command_id, str) or not command_id:
            raise ScenarioError(f"{label}.id must be a non-empty string")
        if command_id in seen_ids:
            raise ScenarioError(f"{label}.id duplicates a previous id: {command_id!r}")
        seen_ids.add(command_id)
        # "command" may be any JSON value; decoding already guaranteed validity.
        normalized_commands.append(
            {"time": time, "node": node, "id": command_id, "command": command["command"]}
        )

    node_events_provided = "nodeEvents" in raw
    node_events = raw.get("nodeEvents", [])
    if not isinstance(node_events, list):
        raise ScenarioError("nodeEvents must be a list")
    normalized_node_events = []
    last_action: dict[str, str] = {}
    for index, event in enumerate(node_events):
        label = f"nodeEvents[{index}]"
        if not isinstance(event, dict):
            raise ScenarioError(f"{label} must be an object")
        unknown = sorted(set(event) - _NODE_EVENT_FIELDS)
        if unknown:
            raise ScenarioError(f"{label} has unknown field(s): {', '.join(unknown)}")
        missing = sorted(_NODE_EVENT_FIELDS - set(event))
        if missing:
            raise ScenarioError(f"{label} missing field(s): {', '.join(missing)}")
        time = _require_int(event["time"], f"{label}.time", 0)
        if time > duration:
            raise ScenarioError(f"{label}.time is beyond the simulation duration")
        node = event["node"]
        if not isinstance(node, str) or not node:
            raise ScenarioError(f"{label}.node must be a non-empty string")
        if node not in node_set:
            raise ScenarioError(f"{label}.node references unknown node: {node!r}")
        action = event["action"]
        if action not in ("crash", "restart"):
            raise ScenarioError(f"{label}.action must be crash or restart")
        previous = last_action.get(node)
        if previous is None and action != "crash":
            raise ScenarioError(f"{label}: first event for node {node!r} must be crash")
        if previous == action:
            raise ScenarioError(
                f"{label}: events for node {node!r} must alternate crash and restart"
            )
        last_action[node] = action
        normalized_node_events.append({"time": time, "node": node, "action": action})

    snapshot_threshold = None
    if "snapshotThreshold" in raw:
        snapshot_threshold = _require_int(
            raw["snapshotThreshold"], "snapshotThreshold", 1
        )

    has_initial_members = "initialMembers" in raw
    has_membership_changes = "membershipChanges" in raw
    if has_initial_members != has_membership_changes:
        raise ScenarioError(
            "initialMembers and membershipChanges must be provided together"
        )

    initial_members: list[str] | None = None
    membership_enabled = has_initial_members
    seen_change_ids: set[str] = set()
    if has_initial_members:
        raw_initial = raw["initialMembers"]
        if not isinstance(raw_initial, list) or len(raw_initial) < 3:
            raise ScenarioError(
                "initialMembers must be a list of at least three node names"
            )
        for name in raw_initial:
            if not isinstance(name, str) or not name:
                raise ScenarioError("initialMembers entries must be non-empty strings")
            if name not in node_set:
                raise ScenarioError(
                    f"initialMembers references unknown node: {name!r}"
                )
        if len(set(raw_initial)) != len(raw_initial):
            raise ScenarioError("initialMembers entries must be unique")
        initial_members = list(raw_initial)

        raw_changes = raw["membershipChanges"]
        if not isinstance(raw_changes, list):
            raise ScenarioError("membershipChanges must be a list")
        normalized_changes = []
        for index, change in enumerate(raw_changes):
            label = f"membershipChanges[{index}]"
            if not isinstance(change, dict):
                raise ScenarioError(f"{label} must be an object")
            unknown = sorted(set(change) - _MEMBERSHIP_CHANGE_FIELDS)
            if unknown:
                raise ScenarioError(f"{label} has unknown field(s): {', '.join(unknown)}")
            missing = sorted(_MEMBERSHIP_CHANGE_FIELDS - set(change))
            if missing:
                raise ScenarioError(f"{label} missing field(s): {', '.join(missing)}")
            time = _require_int(change["time"], f"{label}.time", 0)
            if time > duration:
                raise ScenarioError(f"{label}.time is beyond the simulation duration")
            node = change["node"]
            if not isinstance(node, str) or not node:
                raise ScenarioError(f"{label}.node must be a non-empty string")
            if node not in node_set:
                raise ScenarioError(f"{label}.node references unknown node: {node!r}")
            change_id = change["id"]
            if not isinstance(change_id, str) or not change_id:
                raise ScenarioError(f"{label}.id must be a non-empty string")
            if change_id in seen_change_ids:
                raise ScenarioError(
                    f"{label}.id duplicates a previous id: {change_id!r}"
                )
            seen_change_ids.add(change_id)
            if change_id in seen_ids:
                raise ScenarioError(
                    f"{label}.id duplicates a clientCommands id: {change_id!r}"
                )
            action = change["action"]
            if action not in ("add", "remove"):
                raise ScenarioError(f"{label}.action must be add or remove")
            member = change["member"]
            if not isinstance(member, str) or not member:
                raise ScenarioError(f"{label}.member must be a non-empty string")
            if member not in node_set:
                raise ScenarioError(
                    f"{label}.member references unknown node: {member!r}"
                )
            normalized_changes.append(
                {
                    "time": time,
                    "node": node,
                    "id": change_id,
                    "action": action,
                    "member": member,
                }
            )

    read_queries_provided = "readQueries" in raw
    read_queries = raw.get("readQueries", [])
    if not isinstance(read_queries, list):
        raise ScenarioError("readQueries must be a list")
    normalized_read_queries = []
    seen_read_ids: set[str] = set()
    for index, query in enumerate(read_queries):
        label = f"readQueries[{index}]"
        if not isinstance(query, dict):
            raise ScenarioError(f"{label} must be an object")
        unknown = sorted(set(query) - _READ_QUERY_FIELDS)
        if unknown:
            raise ScenarioError(f"{label} has unknown field(s): {', '.join(unknown)}")
        missing = sorted(_READ_QUERY_FIELDS - set(query))
        if missing:
            raise ScenarioError(f"{label} missing field(s): {', '.join(missing)}")
        time = _require_int(query["time"], f"{label}.time", 0)
        if time > duration:
            raise ScenarioError(f"{label}.time is beyond the simulation duration")
        node = query["node"]
        if not isinstance(node, str) or not node:
            raise ScenarioError(f"{label}.node must be a non-empty string")
        if node not in node_set:
            raise ScenarioError(f"{label}.node references unknown node: {node!r}")
        query_id = query["id"]
        if not isinstance(query_id, str) or not query_id:
            raise ScenarioError(f"{label}.id must be a non-empty string")
        if query_id in seen_read_ids:
            raise ScenarioError(f"{label}.id duplicates a previous id: {query_id!r}")
        if query_id in seen_ids:
            raise ScenarioError(
                f"{label}.id duplicates a clientCommands id: {query_id!r}"
            )
        if query_id in seen_change_ids:
            raise ScenarioError(
                f"{label}.id duplicates a membershipChanges id: {query_id!r}"
            )
        seen_read_ids.add(query_id)
        normalized_read_queries.append({"time": time, "node": node, "id": query_id})

    liveness_provided = "livenessChecks" in raw
    liveness_checks = raw.get("livenessChecks", [])
    if not isinstance(liveness_checks, list):
        raise ScenarioError("livenessChecks must be a list")
    normalized_liveness_checks = []
    seen_check_ids: set[str] = set()
    for index, check in enumerate(liveness_checks):
        label = f"livenessChecks[{index}]"
        if not isinstance(check, dict):
            raise ScenarioError(f"{label} must be an object")
        unknown = sorted(set(check) - _LIVENESS_CHECK_FIELDS)
        if unknown:
            raise ScenarioError(f"{label} has unknown field(s): {', '.join(unknown)}")
        missing = sorted(_LIVENESS_CHECK_FIELDS - {"target"} - set(check))
        if missing:
            raise ScenarioError(f"{label} missing field(s): {', '.join(missing)}")
        check_id = check["id"]
        if not isinstance(check_id, str) or not check_id:
            raise ScenarioError(f"{label}.id must be a non-empty string")
        if check_id in seen_check_ids:
            raise ScenarioError(f"{label}.id duplicates a previous id: {check_id!r}")
        seen_check_ids.add(check_id)
        check_type = check["type"]
        if check_type not in _LIVENESS_TYPES:
            raise ScenarioError(
                f"{label}.type must be one of: {', '.join(_LIVENESS_TYPES)}"
            )
        start_time = _require_int(check["startTime"], f"{label}.startTime", 0)
        if start_time > duration:
            raise ScenarioError(f"{label}.startTime is beyond the simulation duration")
        deadline = _require_int(check["deadline"], f"{label}.deadline", 0)
        if deadline > duration:
            raise ScenarioError(f"{label}.deadline is beyond the simulation duration")
        if start_time > deadline:
            raise ScenarioError(f"{label}.startTime must not be greater than deadline")
        if check_type == "leaderElected":
            if "target" in check:
                raise ScenarioError(f"{label} leaderElected must not have a target")
            target = None
        else:
            if "target" not in check:
                raise ScenarioError(f"{label} {check_type} requires a target")
            target = check["target"]
            if not isinstance(target, str) or not target:
                raise ScenarioError(f"{label}.target must be a non-empty string")
            container = _LIVENESS_TARGET_TYPES[check_type]
            if container == "clientCommands" and target not in seen_ids:
                raise ScenarioError(
                    f"{label}.target references an unknown clientCommands id: {target!r}"
                )
            if container == "readQueries" and target not in seen_read_ids:
                raise ScenarioError(
                    f"{label}.target references an unknown readQueries id: {target!r}"
                )
            if container == "membershipChanges" and target not in seen_change_ids:
                raise ScenarioError(
                    f"{label}.target references an unknown membershipChanges id: {target!r}"
                )
        normalized_liveness_checks.append(
            {
                "id": check_id,
                "type": check_type,
                "startTime": start_time,
                "deadline": deadline,
                "target": target,
            }
        )

    return {
        "nodes": list(nodes),
        "duration": duration,
        "electionTimeouts": timeouts,
        "heartbeatInterval": heartbeat,
        "messageDelay": delay,
        "faults": normalized_faults,
        "messageFaults": normalized_message_faults,
        "clientCommands": normalized_commands,
        "nodeEvents": normalized_node_events,
        "nodeEventsProvided": node_events_provided,
        "snapshotThreshold": snapshot_threshold,
        "membershipEnabled": membership_enabled,
        "initialMembers": initial_members,
        "membershipChanges": normalized_changes if has_initial_members else None,
        "readQueries": normalized_read_queries,
        "readQueriesProvided": read_queries_provided,
        "livenessChecks": normalized_liveness_checks,
        "livenessChecksProvided": liveness_provided,
        "preVote": pre_vote,
    }


class _Node:
    __slots__ = (
        "role",
        "term",
        "voted_for",
        "known_leader",
        "votes",
        "timeout_gen",
        "log",
        "snapshot_index",
        "snapshot_term",
        "snapshot_config",
        "commit_index",
        "last_applied",
        "applied",
        "next_index",
        "match_index",
        "online",
        "restart_count",
        "pre_round",
        "pre_term",
        "pre_votes",
        "pre_config",
        "leader_contact",
    )

    def __init__(self) -> None:
        self.role = ROLE_FOLLOWER
        self.term = 0
        self.voted_for: str | None = None
        self.known_leader: str | None = None
        self.votes: set[str] = set()
        self.timeout_gen = 0
        # Log entries keep their global indices: self.log holds only the
        # uncompacted suffix, so entry for global index i is self.log[i - 1 -
        # self.snapshot_index]. snapshot_index/snapshot_term describe the last
        # entry folded into the (modeled) snapshot; 0 means no snapshot yet.
        self.log: list[dict] = []
        self.snapshot_index = 0
        self.snapshot_term = 0
        # Configuration in effect at snapshot_index (None before any
        # snapshot). Config entries can be compacted into snapshots like any
        # committed entry, so membership survives compaction.
        self.snapshot_config: dict | None = None
        self.commit_index = 0
        self.last_applied = 0
        self.applied: list[dict] = []
        # Leader-only replication progress, keyed by peer name.
        self.next_index: dict[str, int] = {}
        self.match_index: dict[str, int] = {}
        # Crash/restart lifecycle. term, voted_for, log, snapshot_index,
        # snapshot_term, snapshot_config, commit_index, last_applied, applied
        # and the configuration encoded in the log all model persisted state:
        # every change to them is made (synchronously) before the response that
        # depends on it, so they survive a crash and are simply kept on
        # restart. Everything else is volatile and is reset on restart.
        self.online = True
        self.restart_count = 0
        # Optional pre-vote phase state (volatile; never persisted). A
        # preCandidate probes with prospective term pre_term = term + 1 and
        # round pre_round without changing term or voted_for; pre_votes holds
        # the peers that granted the active round and pre_config the electorate
        # that round is decided under. All four are reset on restart.
        self.pre_round = 0
        self.pre_term = 0
        self.pre_votes: set[str] = set()
        self.pre_config: dict | None = None
        # Virtual time of the most recent heartbeat/appendEntries/
        # installSnapshot accepted from a current-term leader, or -1 when no
        # such contact has occurred since the term began (or since startup or
        # restart). A pre-vote is granted only when no contact is recorded or
        # the local election timeout has elapsed since the latest contact.
        # Purely internal: it is never serialized.
        self.leader_contact = -1

    def last_log_index(self) -> int:
        return self.snapshot_index + len(self.log)

    def last_log_term(self) -> int:
        return self.log[-1]["term"] if self.log else self.snapshot_term

    def term_at(self, index: int) -> int:
        if index <= 0:
            return 0
        if index == self.snapshot_index:
            return self.snapshot_term
        if index < self.snapshot_index:
            raise IndexError(f"index {index} is covered by the snapshot")
        return self.log[index - 1 - self.snapshot_index]["term"]

    def has_entry(self, index: int) -> bool:
        return self.snapshot_index < index <= self.last_log_index()

    def config_at(self, index: int, initial_config: dict) -> dict | None:
        """The configuration in effect immediately *before* the entry at
        ``index`` is applied: the latest config entry with a smaller index, or
        the snapshot config / initial configuration. Returns None when no
        configuration entry precedes ``index`` (the caller substitutes the
        initial configuration)."""
        config = self.snapshot_config if self.snapshot_config else initial_config
        upper = min(index - 1, self.last_log_index())
        for i in range(self.snapshot_index + 1, upper + 1):
            entry = self.log[i - 1 - self.snapshot_index]
            if entry.get("kind") == KIND_CONFIG:
                config = entry["config"]
        return config

    def latest_config(self, initial_config: dict) -> dict:
        """The newest configuration present in this node's log (or its
        snapshot), whether or not it is committed or applied."""
        result = self.snapshot_config if self.snapshot_config else initial_config
        for entry in self.log:
            if entry.get("kind") == KIND_CONFIG:
                result = entry["config"]
        return result

    def committed_config(self, initial_config: dict) -> dict:
        """The configuration established by the newest committed config
        entry (or the snapshot config, which only covers committed state)."""
        config = self.snapshot_config if self.snapshot_config else initial_config
        upper = min(self.commit_index, self.last_log_index())
        for i in range(self.snapshot_index + 1, upper + 1):
            entry = self.log[i - 1 - self.snapshot_index]
            if entry.get("kind") == KIND_CONFIG:
                config = entry["config"]
        return config


class _Simulator:
    def __init__(self, config: dict) -> None:
        self.node_names: list[str] = config["nodes"]
        self.duration: int = config["duration"]
        self.timeouts: dict[str, int] = config["electionTimeouts"]
        self.heartbeat_interval: int = config["heartbeatInterval"]
        self.delay: int = config["messageDelay"]
        self.faults: list[dict] = config["faults"]
        # Per-message fault rules, keyed by the full selector
        # (from, to, message, occurrence); the per-(from, to, message) send
        # counter below numbers actual sends from the start of the run.
        self.message_faults: dict[tuple, dict] = {
            (rule["from"], rule["to"], rule["message"], rule["occurrence"]): rule
            for rule in config["messageFaults"]
        }
        self.message_fault_counts: dict[tuple, int] = {}
        self.commands: list[dict] = config["clientCommands"]
        self.node_events: list[dict] = config["nodeEvents"]
        self.node_events_provided: bool = config["nodeEventsProvided"]
        self.pre_vote_enabled: bool = config["preVote"]
        self.snapshot_threshold: int | None = config["snapshotThreshold"]
        self.membership_enabled: bool = config["membershipEnabled"]
        self.changes: list[dict] = config["membershipChanges"] or []
        if self.membership_enabled:
            initial_members = frozenset(config["initialMembers"])
            self.initial_config: dict = {
                "type": CONFIG_STABLE,
                "old": initial_members,
                "new": initial_members,
            }
        else:
            all_nodes = frozenset(self.node_names)
            self.initial_config = {"type": CONFIG_STABLE, "old": all_nodes, "new": all_nodes}
        self.state = {name: _Node() for name in self.node_names}
        self.index = {name: i for i, name in enumerate(self.node_names)}
        self.timeline: list[dict] = []
        self.leaders_by_term: dict[int, list[str]] = {}
        self.partition: list[frozenset[str]] | None = None
        self.queue: list[tuple] = []
        self.send_counter = 0
        self.now = 0
        # While draining client commands (and the replication cascade they
        # trigger), new messages land in the REACTION phase instead of the
        # regular MESSAGE phase.
        self.reaction_phase = False
        # Commands rejected at the door (target was not leader, or was down)
        # never reach a log. Final committed / superseded / pending outcomes
        # are derived from the end state; reason and knownLeader are captured
        # at rejection time.
        self.rejected: dict[str, dict] = {}
        # Membership-change bookkeeping.
        # change_id -> {"node", "action", "member", "result", "index"?, "term"?,
        #               "jointIndex"?, "stableIndex"?, "reason"?}
        self.change_results: dict[str, dict] = {}
        # change_id of the change whose joint entry is committed but whose
        # stable entry has not been appended yet, if any.
        # Learner catch-up state for the in-progress add: once the target
        # learner's matchIndex reaches the pre-joint log end, the leader
        # appends the joint config entry.
        self.pending_catchup: dict | None = None
        # Read-only query bookkeeping.
        self.read_queries: list[dict] = config["readQueries"]
        self.read_queries_provided: bool = config["readQueriesProvided"]
        # query id -> {"node", "term", "readIndex", "config", "acks",
        #              "required"} for accepted queries still awaiting a
        # same-term majority confirmation under the recorded configuration.
        self.pending_reads: dict[str, dict] = {}
        # query id -> final outcome for queries resolved during the run.
        self.read_results: dict[str, dict] = {}
        # query id -> client-command ids already committed when the query was
        # accepted; a completed read omitting any of them is a stale read.
        self.read_required: dict[str, set[str]] = {}
        # Client-command ids committed so far (leader-side commit advances).
        self.committed_command_ids: set[str] = set()
        # Client-command ids accepted (appended to a leader's log) at least
        # once; together with the rejected map and current log presence this
        # distinguishes "not submitted yet / pending" from "superseded".
        self.accepted_command_ids: set[str] = set()
        # Optional liveness checks. Each one is evaluated at every virtual
        # timestamp in its [startTime, deadline] window, but only after all
        # pre-existing events sharing that timestamp (and their zero-delay
        # reaction cascades) have drained; checks at the same timestamp run in
        # input order.
        self.liveness_checks: list[dict] = config["livenessChecks"]
        self.liveness_provided: bool = config["livenessChecksProvided"]
        # check id -> finished result entry (status satisfied/failed).
        self.liveness_results: dict[str, dict] = {}
        # Whether an online leader exists at the current evaluation point.
        self.leader_online = False
        # change id -> virtual time its stable configuration entry was first
        # applied on any node (the moment the change is committed).
        self.stable_commit_times: dict[str, int] = {}

    def run(self) -> dict:
        for order, fault in enumerate(self.faults):
            heapq.heappush(self.queue, (fault["time"], _KIND_FAULT, order, fault))
        for order, event in enumerate(self.node_events):
            heapq.heappush(self.queue, (event["time"], _KIND_NODE_EVENT, order, event))
        for order, command in enumerate(self.commands):
            heapq.heappush(self.queue, (command["time"], _KIND_CLIENT, order, command))
        for order, change in enumerate(self.changes):
            heapq.heappush(self.queue, (change["time"], _KIND_MEMBERSHIP, order, change))
        for order, query in enumerate(self.read_queries):
            heapq.heappush(self.queue, (query["time"], _KIND_READ, order, query))
        for name in self.node_names:
            if self._is_voter(name, self.initial_config):
                heapq.heappush(self.queue, (self.timeouts[name], _KIND_TIMEOUT, self.index[name], (name, 0)))
        if self.liveness_provided:
            # Anchors at every window edge guarantee evaluation also runs at
            # timestamps carrying no pre-existing events; all other timestamps
            # are reached via the drain hook in the loop below.
            anchors = sorted({
                edge
                for check in self.liveness_checks
                for edge in (check["startTime"], check["deadline"])
            })
            for order, edge in enumerate(anchors):
                heapq.heappush(self.queue, (edge, _KIND_LIVENESS, order, None))
        while self.queue:
            time, kind, _order, payload = heapq.heappop(self.queue)
            if time > self.duration:
                break
            self.now = time
            self.reaction_phase = kind in (_KIND_CLIENT, _KIND_MEMBERSHIP, _KIND_READ, _KIND_REACTION)
            if kind == _KIND_FAULT:
                self._apply_fault(payload)
            elif kind == _KIND_NODE_EVENT:
                self._on_node_event(payload)
            elif kind in (_KIND_MESSAGE, _KIND_REACTION):
                self._deliver(payload)
            elif kind == _KIND_CLIENT:
                self._on_client_command(payload)
            elif kind == _KIND_MEMBERSHIP:
                self._on_membership_change(payload)
            elif kind == _KIND_READ:
                self._on_read_query(payload)
            elif kind == _KIND_TIMEOUT:
                self._on_timeout(*payload)
            elif kind == _KIND_HEARTBEAT:
                self._on_heartbeat(*payload)
            # The liveness anchor itself is a no-op: it only marks a window
            # edge that carries no other events. Either way, once no entry
            # remains for the current timestamp (its zero-delay reactions
            # included), the timestamp has fully drained and the checks run.
            if (
                self.liveness_provided
                and self.liveness_checks
                and (not self.queue or self.queue[0][0] > self.now)
            ):
                self._evaluate_liveness(self.now)
        return self._report()

    # -- timeline helpers -------------------------------------------------

    def _record(self, entry: dict) -> None:
        self.timeline.append({"seq": len(self.timeline) + 1, "time": self.now, **entry})

    def _record_state_change(self, name: str, reason: str) -> None:
        st = self.state[name]
        self._record({"type": "stateChange", "node": name, "term": st.term, "role": st.role, "reason": reason})

    # -- configuration -------------------------------------------------------

    def _command_entry(self, index: int, term: int, command_id: str, command: object) -> dict:
        """A client-command log/applied entry. When membership changes are
        enabled it carries ``kind: "command"`` so configuration entries
        (``kind: "config"``) are unambiguously distinguishable; without the
        feature the historical, untyped shape is preserved byte for byte."""
        entry = {"index": index, "term": term}
        if self.membership_enabled:
            entry["kind"] = KIND_COMMAND
        entry["id"] = command_id
        entry["command"] = command
        return entry

    @staticmethod
    def _config_groups(config: dict) -> tuple[frozenset[str], frozenset[str]]:
        """The (old, new) voter sets of a configuration. Stable configurations
        carry the same set twice; joint configurations carry both."""
        return frozenset(config["old"]), frozenset(config["new"])

    def _config_quorums(self, config: dict) -> list[frozenset[str]]:
        old, new = self._config_groups(config)
        if config.get("type") == CONFIG_JOINT:
            return [old, new]
        return [new]

    def _is_voter(self, name: str, config: dict) -> bool:
        old, new = self._config_groups(config)
        return name in old or name in new

    def _can_vote(self, name: str) -> bool:
        """Current voting/election eligibility from the node's newest
        configuration: learners and nodes not present in the latest config
        neither vote nor campaign. A removed node that learns a configuration
        adding it back regains eligibility."""
        st = self.state[name]
        return self._is_voter(name, st.latest_config(self.initial_config))

    @staticmethod
    def _store_config(config: dict) -> dict:
        old, new = _Simulator._config_groups(config)
        return {
            "type": config.get("type", CONFIG_STABLE),
            "old": sorted(old),
            "new": sorted(new),
        }

    def _joint_config(self, voters: frozenset[str], action: str, member: str) -> dict:
        if action == "add":
            new_voters = voters | {member}
        else:
            new_voters = voters - {member}
        return {"type": CONFIG_JOINT, "old": sorted(voters), "new": sorted(new_voters)}

    @staticmethod
    def _stable_config(voters: frozenset[str]) -> dict:
        ordered = sorted(voters)
        return {"type": CONFIG_STABLE, "old": ordered, "new": ordered}

    def _has_vote_majorities(self, candidate: str, votes: set[str], config: dict) -> bool:
        for group in self._config_quorums(config):
            needed = len(group) // 2 + 1
            if len([v for v in votes if v in group]) < needed:
                return False
        return True

    def _replicated_by_majorities(self, leader: str, index: int, config: dict) -> bool:
        """Whether ``index`` is present on a strict majority of every quorum
        group (the leader itself counts in any group it belongs to)."""
        st = self.state[leader]
        for group in self._config_quorums(config):
            needed = len(group) // 2 + 1
            points = []
            for peer in group:
                if peer == leader:
                    points.append(st.last_log_index())
                else:
                    points.append(st.match_index.get(peer, 0))
            if len([point for point in points if point >= index]) < needed:
                return False
        return True

    # -- state transitions --------------------------------------------------

    def _invalidate_timeout(self, name: str) -> None:
        self.state[name].timeout_gen += 1

    def _reset_timeout(self, name: str) -> None:
        st = self.state[name]
        if not self._can_vote(name):
            # Learners and removed members hold no election timer; bumping the
            # generation cancels any timer scheduled before their membership
            # changed.
            st.timeout_gen += 1
            return
        st.timeout_gen += 1
        heapq.heappush(
            self.queue,
            (self.now + self.timeouts[name], _KIND_TIMEOUT, self.index[name], (name, st.timeout_gen)),
        )

    def _reconcile_election_timer(self, name: str, eligible_before: bool) -> None:
        """Start or cancel a node's election timer when its configuration
        membership changes (e.g. a learner promoted by a replicated joint
        entry, or a member removed by a replicated stable entry)."""
        eligible_after = self._can_vote(name)
        if eligible_after and not eligible_before:
            self._reset_timeout(name)
        elif eligible_before and not eligible_after:
            self._invalidate_timeout(name)

    def _become_follower(self, name: str, term: int, reason: str) -> None:
        st = self.state[name]
        st.role = ROLE_FOLLOWER
        st.term = term
        st.voted_for = None
        st.known_leader = None
        st.votes = set()
        st.next_index = {}
        st.match_index = {}
        # The active round is abandoned; the round counter itself is a
        # lifetime-monotonic nonce so a reply in flight from a superseded
        # round (including one that straddles a restart) can never match a
        # later round.
        st.pre_term = 0
        st.pre_votes = set()
        st.pre_config = None
        # A new term means the previous term's leader contact no longer
        # counts; the heartbeat/appendEntries/installSnapshot handlers mark a
        # fresh contact immediately after stepping down on a leader message.
        st.leader_contact = -1
        self._reset_timeout(name)
        self._record_state_change(name, reason)
        # A deposed leader can no longer vouch for reads it accepted.
        self._abandon_reads(name)

    def _start_election(self, name: str) -> None:
        st = self.state[name]
        # The election is decided under the configuration in place just
        # before the candidate appends anything (joint configs require
        # majorities of both constituent sets).
        config = st.latest_config(self.initial_config)
        st.role = ROLE_CANDIDATE
        st.term += 1
        st.voted_for = name
        st.known_leader = None
        st.votes = {name}
        st.next_index = {}
        st.match_index = {}
        # Winning election traffic is not leader contact: nothing has
        # contacted this node from the new term yet.
        st.leader_contact = -1
        self._reset_timeout(name)
        self._record_state_change(name, "electionTimeout")
        for peer in self.node_names:
            if peer != name and self._is_voter(peer, config):
                self._send(
                    name,
                    peer,
                    {
                        "kind": "requestVote",
                        "term": st.term,
                        "lastLogIndex": st.last_log_index(),
                        "lastLogTerm": st.last_log_term(),
                    },
                )

    def _start_pre_vote(self, name: str) -> None:
        """Enter the pre-candidate phase for a new round. The current term,
        votedFor and the log are all left untouched; only a prospective term
        of term + 1 and a round number are attached to the probes."""
        st = self.state[name]
        config = st.latest_config(self.initial_config)
        st.role = ROLE_PRECANDIDATE
        st.pre_round += 1
        st.pre_term = st.term + 1
        st.pre_votes = {name}
        st.pre_config = config
        self._reset_timeout(name)
        self._record_state_change(name, "electionTimeout")
        for peer in self.node_names:
            if peer != name and self._is_voter(peer, config):
                self._send(
                    name,
                    peer,
                    {
                        "kind": "preVote",
                        "term": st.term,
                        "prospectiveTerm": st.pre_term,
                        "round": st.pre_round,
                        "lastLogIndex": st.last_log_index(),
                        "lastLogTerm": st.last_log_term(),
                    },
                )

    def _promote_from_pre_vote(self, name: str) -> None:
        """A pre-vote round won the required majorities: now start the real
        election, raising the term to the prospective term and persisting the
        self-vote, and broadcast RequestVote in that term."""
        st = self.state[name]
        config = st.pre_config
        prospective = st.pre_term
        st.role = ROLE_CANDIDATE
        st.pre_term = 0
        st.pre_votes = set()
        st.pre_config = None
        st.term = prospective
        st.voted_for = name
        st.known_leader = None
        st.votes = {name}
        st.next_index = {}
        st.match_index = {}
        # Promotion is election traffic, not leader contact.
        st.leader_contact = -1
        self._reset_timeout(name)
        # The transition to a real candidate in the prospective term is the
        # only state event the promotion needs; RequestVote traffic follows.
        self._record_state_change(name, "preVoteMajority")
        for peer in self.node_names:
            if peer != name and self._is_voter(peer, config):
                self._send(
                    name,
                    peer,
                    {
                        "kind": "requestVote",
                        "term": st.term,
                        "lastLogIndex": st.last_log_index(),
                        "lastLogTerm": st.last_log_term(),
                    },
                )

    def _become_leader(self, name: str, config: dict) -> None:
        st = self.state[name]
        st.role = ROLE_LEADER
        st.known_leader = name
        st.votes = set()
        st.pre_term = 0
        st.pre_votes = set()
        st.pre_config = None
        st.timeout_gen += 1  # leaders have no election timeout
        next_index = st.last_log_index() + 1
        # Replication progress is tracked for every other node: voters count
        # towards quorums, learners receive the log but never count.
        st.next_index = {peer: next_index for peer in self.node_names if peer != name}
        st.match_index = {peer: 0 for peer in self.node_names if peer != name}
        self._record_state_change(name, "majority")
        leaders = self.leaders_by_term.setdefault(st.term, [])
        if name not in leaders:
            leaders.append(name)
        self._send_heartbeats(name)
        self._resume_membership_change(name)

    def _resume_membership_change(self, name: str) -> None:
        """Finish a change a previous leader left open. If the newest config
        entry present is a joint entry (with no stable entry following it),
        append the stable entry now: winning this term's election required
        majorities of both joint sets, so the joint entry is known to be on
        those majorities even before commitIndex advanced to it."""
        st = self.state[name]
        if st.latest_config(self.initial_config).get("type") == CONFIG_JOINT:
            joint_entry = None
            # Newest joint entry in the uncompacted log, otherwise the newest
            # one folded into the snapshot's applied history.
            for log_entry in reversed(st.log):
                if log_entry.get("kind") == KIND_CONFIG and log_entry["entryType"] == CONFIG_JOINT:
                    joint_entry = log_entry
                    break
            if joint_entry is None:
                for applied in reversed(st.applied):
                    if (
                        applied.get("kind") == KIND_CONFIG
                        and applied["entryType"] == CONFIG_JOINT
                    ):
                        joint_entry = applied
                        break
            if joint_entry is not None:
                _old, new_voters = self._config_groups(joint_entry["config"])
                stable = self._stable_config(new_voters)
                self._append_config_entry(
                    name,
                    joint_entry["id"],
                    CONFIG_STABLE,
                    stable,
                    joint_entry["action"],
                    joint_entry["member"],
                )
                for peer in self.node_names:
                    if peer != name:
                        self._replicate_to(name, peer)
        if self.pending_catchup is not None:
            if self.pending_catchup["leader"] != name:
                # The old leader was replaced before it appended the joint
                # entry; the unfinished catch-up is abandoned.
                self.pending_catchup = None
            else:
                self._progress_catchup(name)

    # -- messages -----------------------------------------------------------

    @staticmethod
    def _query_id_field(msg: dict) -> dict:
        """Read-confirmation messages (readProbe/readReply) carry the query id
        into their timeline entries; no other message kind has one."""
        return {"id": msg["id"]} if "id" in msg else {}

    @staticmethod
    def _pre_vote_fields(msg: dict) -> dict:
        """Pre-vote messages carry their round and prospective term into every
        timeline entry; no other message kind has either."""
        fields: dict = {}
        if "round" in msg:
            fields["round"] = msg["round"]
        if "prospectiveTerm" in msg:
            fields["prospectiveTerm"] = msg["prospectiveTerm"]
        return fields

    def _send(self, src: str, dst: str, msg: dict) -> None:
        self._record({
            "type": "messageSend",
            "node": src,
            "peer": dst,
            "message": msg["kind"],
            "term": msg["term"],
            **self._query_id_field(msg),
            **self._pre_vote_fields(msg),
        })
        self.send_counter += 1
        envelope = {**msg, "src": src, "dst": dst}
        # A messageFaults rule matches the occurrence-th actual send of its
        # (from, to, message) selector. The fault is recorded right after the
        # send; a drop replaces delivery with a dropped/messageFault result at
        # the originally scheduled arrival, a delay shifts the arrival itself.
        count_key = (src, dst, msg["kind"])
        occurrence = self.message_fault_counts.get(count_key, 0) + 1
        self.message_fault_counts[count_key] = occurrence
        rule = self.message_faults.get((src, dst, msg["kind"], occurrence))
        extra_delay = 0
        if rule is not None:
            scheduled = self.now + self.delay
            fault_entry = {
                "type": "messageFault",
                "rule": rule["index"],
                "from": src,
                "to": dst,
                "message": msg["kind"],
                "occurrence": occurrence,
                "action": rule["action"],
                "scheduledTime": scheduled,
            }
            if rule["action"] == "drop":
                envelope["faultDrop"] = True
            else:
                extra_delay = rule["delay"]
                fault_entry["arrivalTime"] = scheduled + extra_delay
            self._record(fault_entry)
        effective_delay = self.delay + extra_delay
        # Zero-delay replication triggered while draining a client-command
        # batch shares the batch's timestamp and must follow the remaining
        # client commands; a positive delay lands strictly in the future and
        # queues as a normal message arrival.
        in_phase = self.reaction_phase and effective_delay == 0
        kind = _KIND_REACTION if in_phase else _KIND_MESSAGE
        heapq.heappush(self.queue, (self.now + effective_delay, kind, self.send_counter, envelope))

    def _send_heartbeats(self, name: str) -> None:
        """Per peer, send either a log-carrying appendEntries (when the peer is
        behind) or a bare heartbeat (when its log already matches). Mixing the
        two would let an empty heartbeat's leaderCommit make a divergent peer
        apply entries that the appendEntries is about to overwrite. The
        appendEntries handler truncates, appends and advances the commit in one
        atomic step, so it alone is safe for a lagging peer."""
        st = self.state[name]
        for peer in self.node_names:
            if peer == name:
                continue
            if st.match_index[peer] < st.last_log_index():
                self._replicate_to(name, peer)
            else:
                self._send(
                    name,
                    peer,
                    {"kind": "heartbeat", "term": st.term, "leaderCommit": st.commit_index},
                )
        heapq.heappush(
            self.queue,
            (self.now + self.heartbeat_interval, _KIND_HEARTBEAT, self.index[name], (name, st.term)),
        )

    def _replicate_to(self, name: str, peer: str) -> None:
        """Send the next due message for one peer: an installSnapshot when the
        peer's next position is already covered by the leader's snapshot,
        otherwise an appendEntries carrying the uncompacted suffix slice."""
        st = self.state[name]
        next_idx = st.next_index[peer]
        if next_idx <= st.snapshot_index:
            # The snapshot bundles the applied state through lastIncludedIndex.
            snapshot_entries = [dict(entry) for entry in st.applied[: st.snapshot_index]]
            self._send(
                name,
                peer,
                {
                    "kind": "installSnapshot",
                    "term": st.term,
                    "lastIncludedIndex": st.snapshot_index,
                    "lastIncludedTerm": st.snapshot_term,
                    "entries": snapshot_entries,
                },
            )
            return
        prev_idx = next_idx - 1
        entries = [dict(entry) for entry in st.log[next_idx - 1 - st.snapshot_index:]]
        self._send(
            name,
            peer,
            {
                "kind": "appendEntries",
                "term": st.term,
                "prevLogIndex": prev_idx,
                "prevLogTerm": st.term_at(prev_idx),
                "entries": entries,
                "leaderCommit": st.commit_index,
            },
        )

    def _connected(self, a: str, b: str) -> bool:
        if self.partition is None:
            return True
        return any(a in group and b in group for group in self.partition)

    def _deliver(self, msg: dict) -> None:
        src, dst = msg["src"], msg["dst"]
        if msg.get("faultDrop"):
            # A messageFaults drop rule: the message never reaches the
            # receiver, reported at its originally scheduled arrival time.
            self._record({
                "type": "messageResult",
                "node": dst,
                "peer": src,
                "message": msg["kind"],
                "term": msg["term"],
                **self._query_id_field(msg),
                **self._pre_vote_fields(msg),
                "result": "dropped",
                "reason": "messageFault",
            })
            return
        if not self.state[dst].online:
            # The destination crashed after this message was sent; it is
            # dropped on arrival. Messages the crashed node itself sent
            # earlier are unaffected and still land at their original time.
            self._record({
                "type": "messageResult",
                "node": dst,
                "peer": src,
                "message": msg["kind"],
                "term": msg["term"],
                **self._query_id_field(msg),
                **self._pre_vote_fields(msg),
                "result": "dropped",
                "reason": "nodeDown",
            })
            return
        if not self._connected(src, dst):
            self._record({
                "type": "messageResult",
                "node": dst,
                "peer": src,
                "message": msg["kind"],
                "term": msg["term"],
                **self._query_id_field(msg),
                **self._pre_vote_fields(msg),
                "result": "dropped",
                "reason": "partition",
            })
            return
        kind = msg["kind"]
        if kind == "requestVote":
            self._handle_request_vote(msg)
        elif kind == "voteReply":
            self._handle_vote_reply(msg)
        elif kind == "preVote":
            self._handle_pre_vote(msg)
        elif kind == "preVoteReply":
            self._handle_pre_vote_reply(msg)
        elif kind == "heartbeat":
            self._handle_heartbeat(msg)
        elif kind == "appendEntries":
            self._handle_append_entries(msg)
        elif kind == "installSnapshot":
            self._handle_install_snapshot(msg)
        elif kind == "installSnapshotReply":
            self._handle_snapshot_reply(msg)
        elif kind == "readProbe":
            self._handle_read_probe(msg)
        elif kind == "readReply":
            self._handle_read_reply(msg)
        else:
            self._handle_append_reply(msg)

    def _handle_request_vote(self, msg: dict) -> None:
        src, dst = msg["src"], msg["dst"]
        st = self.state[dst]
        # A higher term clears voted_for before the vote decision is made.
        effective_voted_for = None if msg["term"] > st.term else st.voted_for
        up_to_date = (
            msg["lastLogTerm"] > st.last_log_term()
            or (
                msg["lastLogTerm"] == st.last_log_term()
                and msg["lastLogIndex"] >= st.last_log_index()
            )
        )
        # Learners and removed members never grant a vote; candidates only
        # solicit voters, so stale RVs reaching a demoted node are denied.
        eligible_voter = self._can_vote(dst)
        granted = (
            eligible_voter
            and msg["term"] >= st.term
            and up_to_date
            and (effective_voted_for is None or effective_voted_for == src)
        )
        self._record({
            "type": "messageResult",
            "node": dst,
            "peer": src,
            "message": "requestVote",
            "term": msg["term"],
            "result": "delivered",
            "detail": "voteGranted" if granted else "voteDenied",
        })
        if msg["term"] > st.term:
            self._become_follower(dst, msg["term"], "higherTermMessage")
        if granted:
            st.voted_for = src
        self._send(dst, src, {"kind": "voteReply", "term": st.term, "granted": granted})

    def _handle_vote_reply(self, msg: dict) -> None:
        src, dst = msg["src"], msg["dst"]
        st = self.state[dst]
        detail = "ignored"
        elected = False
        election_config = st.latest_config(self.initial_config)
        if msg["term"] > st.term:
            detail = "higherTerm"
        elif st.role == ROLE_CANDIDATE and msg["term"] == st.term and msg["granted"]:
            st.votes.add(src)
            detail = "voteCounted"
            elected = self._has_vote_majorities(dst, st.votes, election_config)
        self._record({
            "type": "messageResult",
            "node": dst,
            "peer": src,
            "message": "voteReply",
            "term": msg["term"],
            "result": "delivered",
            "detail": detail,
        })
        if msg["term"] > st.term:
            self._become_follower(dst, msg["term"], "higherTermMessage")
        elif elected:
            self._become_leader(dst, election_config)

    # -- pre-vote (optional phase) ------------------------------------------

    def _pre_vote_deadline_passed(self, name: str) -> bool:
        """Whether a current-term leader contact is old enough that the local
        election deadline has elapsed. No recorded contact (startup, restart
        or term entered through election traffic) always passes."""
        contact = self.state[name].leader_contact
        return contact < 0 or self.now >= contact + self.timeouts[name]

    def _handle_pre_vote(self, msg: dict) -> None:
        src, dst = msg["src"], msg["dst"]
        st = self.state[dst]
        up_to_date = (
            msg["lastLogTerm"] > st.last_log_term()
            or (
                msg["lastLogTerm"] == st.last_log_term()
                and msg["lastLogIndex"] >= st.last_log_index()
            )
        )
        # A pre-vote never changes the receiver's term, vote or timer; it is
        # granted solely on merit and on the absence of a recently heard
        # current-term leader. Learners and removed members have no vote, the
        # current leader never grants one, a stale prospective term is
        # refused, and a node that heard a viable leader within its election
        # deadline refuses so it cannot help a partitioned peer disrupt the
        # stable leader.
        granted = (
            self._can_vote(dst)
            and st.role != ROLE_LEADER
            and msg["prospectiveTerm"] >= st.term + 1
            and up_to_date
            and self._pre_vote_deadline_passed(dst)
        )
        self._record({
            "type": "messageResult",
            "node": dst,
            "peer": src,
            "message": "preVote",
            "term": msg["term"],
            "round": msg["round"],
            "prospectiveTerm": msg["prospectiveTerm"],
            "result": "delivered",
            "detail": "granted" if granted else "rejected",
        })
        # Reply with the receiver's *current* (unchanged) term so a
        # pre-candidate facing a higher real term learns it and stands down.
        self._send(
            dst,
            src,
            {
                "kind": "preVoteReply",
                "term": st.term,
                "prospectiveTerm": msg["prospectiveTerm"],
                "round": msg["round"],
                "granted": granted,
            },
        )

    def _handle_pre_vote_reply(self, msg: dict) -> None:
        src, dst = msg["src"], msg["dst"]
        st = self.state[dst]
        detail = "staleRound"
        won = False
        if msg["term"] > st.term:
            # A reply carrying a higher real term ends the round outright.
            detail = "higherTerm"
        elif (
            st.role == ROLE_PRECANDIDATE
            and msg["round"] == st.pre_round
            and msg["prospectiveTerm"] == st.pre_term
        ):
            if msg["granted"]:
                st.pre_votes.add(src)
                detail = "granted"
                if self._can_vote(dst) and self._has_vote_majorities(
                    dst, st.pre_votes, st.pre_config
                ):
                    won = True
            else:
                detail = "rejected"
        self._record({
            "type": "messageResult",
            "node": dst,
            "peer": src,
            "message": "preVoteReply",
            "term": msg["term"],
            "round": msg["round"],
            "prospectiveTerm": msg["prospectiveTerm"],
            "result": "delivered",
            "detail": detail,
        })
        if msg["term"] > st.term:
            self._become_follower(dst, msg["term"], "higherTermMessage")
        elif won:
            # Still online (delivery ensured it), eligible, same round and
            # unchanged term: raise the term to the prospective term and open
            # the real election.
            self._promote_from_pre_vote(dst)

    def _handle_heartbeat(self, msg: dict) -> None:
        src, dst = msg["src"], msg["dst"]
        st = self.state[dst]
        accepted = msg["term"] >= st.term
        self._record({
            "type": "messageResult",
            "node": dst,
            "peer": src,
            "message": "heartbeat",
            "term": msg["term"],
            "result": "delivered",
            "detail": "accepted" if accepted else "staleTerm",
        })
        if not accepted:
            return
        if msg["term"] > st.term or st.role != ROLE_FOLLOWER:
            self._become_follower(dst, msg["term"], "heartbeat")
        else:
            self._reset_timeout(dst)
        st.known_leader = src
        # A current-term heartbeat is leader contact: it suppresses pre-vote
        # grants until the local election deadline next elapses (and stepping
        # down above canceled any active pre-vote round).
        st.leader_contact = self.now
        # Heartbeats carry leaderCommit even when no entry is in flight.
        if msg.get("leaderCommit", 0) > st.commit_index:
            st.commit_index = min(msg["leaderCommit"], st.last_log_index())
        self._advance_apply(dst)

    def _handle_append_entries(self, msg: dict) -> None:
        src, dst = msg["src"], msg["dst"]
        st = self.state[dst]
        if msg["term"] < st.term:
            self._record({
                "type": "messageResult",
                "node": dst,
                "peer": src,
                "message": "appendEntries",
                "term": msg["term"],
                "result": "delivered",
                "detail": "staleTerm",
            })
            self._send(
                dst,
                src,
                {"kind": "appendReply", "term": st.term, "success": False, "matchIndex": 0},
            )
            return

        if msg["term"] > st.term or st.role != ROLE_FOLLOWER:
            self._become_follower(dst, msg["term"], "appendEntries")
        else:
            self._reset_timeout(dst)
        st.known_leader = src
        # A current-term appendEntries (even one that reports a prefix
        # conflict below) proves leader contact and suppresses pre-vote grants
        # until the next election deadline.
        st.leader_contact = self.now

        prev_index = msg["prevLogIndex"]
        prefix_ok = (
            prev_index >= st.snapshot_index
            and prev_index <= st.last_log_index()
            and st.term_at(prev_index) == msg["prevLogTerm"]
        )
        if not prefix_ok:
            self._record({
                "type": "messageResult",
                "node": dst,
                "peer": src,
                "message": "appendEntries",
                "term": msg["term"],
                "result": "delivered",
                "detail": "conflict",
                "prevLogIndex": prev_index,
            })
            self._send(
                dst,
                src,
                {"kind": "appendReply", "term": st.term, "success": False, "matchIndex": 0},
            )
            return

        # Latest configuration decides voting/campaigning as soon as an entry
        # is appended, so start or stop the election timer when the batch
        # changes this node's membership. Compute eligibility before any
        # truncation or append.
        eligible_before = self._can_vote(dst)

        # Truncate the suffix at the first position whose term differs.
        conflict_index = 0
        for offset, entry in enumerate(msg["entries"]):
            index = prev_index + 1 + offset
            if st.has_entry(index) and st.log[index - 1 - st.snapshot_index]["term"] != entry["term"]:
                conflict_index = index
                del st.log[index - 1 - st.snapshot_index:]
                break

        # Append whatever is not already present with a matching term.
        appended = 0
        for offset, entry in enumerate(msg["entries"]):
            index = prev_index + 1 + offset
            if index > st.last_log_index():
                if entry.get("kind") == KIND_CONFIG:
                    stored = {
                        "index": index,
                        "term": entry["term"],
                        "kind": KIND_CONFIG,
                        "id": entry["id"],
                        "entryType": entry["entryType"],
                        "config": entry["config"],
                        "action": entry["action"],
                        "member": entry["member"],
                    }
                else:
                    stored = self._command_entry(
                        index, entry["term"], entry["id"], entry["command"]
                    )
                st.log.append(stored)
                appended += 1

        self._reconcile_election_timer(dst, eligible_before)

        config_entries = [
            {
                "index": entry["index"],
                "id": entry["id"],
                "entryType": entry["entryType"],
            }
            for entry in msg["entries"]
            if entry.get("kind") == KIND_CONFIG
        ]

